export function soTypeFor(insdcType: string): { type: string; original?: string } {
  if (SO_FEATURE_NAMES.has(insdcType) || SO_FEATURE_IDS.has(insdcType)) return { type: insdcType };
  const mapped = INSDC_TO_SO[insdcType];
  if (mapped) return mapped === insdcType ? { type: mapped } : { type: mapped, original: insdcType };
  return { type: 'sequence_feature', original: insdcType };
}
